function largestRunSum(nums: number[]): number {
  let prefix = 0, lowest = 0, best = -Infinity;
  for (const x of nums) {
    prefix += x;
    best = Math.max(best, prefix - lowest);
    lowest = Math.min(lowest, prefix);
  }
  return best;
}

